class Solution {
public:
    ListNode* mergeKLists(vector<ListNode*>&lists) 
    {
        //instead of checking everytime k lists and appending minimum of all to our answer list, maintain priority queue which gives us the minimum element in O(1) instead of O(K), where K is number of lists.
        //Sure O(logN) time would be required to insert and delete but its far off better than linear time
        priority_queue<pair<int,int>,vector<pair<int,int>>,greater<pair<int,int>>>minheap;//value,index of ListNode in vector
        for(int i=0;i<lists.size();i++)
        {
            if(lists[i]!=NULL)
            {
                minheap.push({lists[i]->val,i});
            }
        }
        if(minheap.empty())//Edge Case Handling
        {
            return NULL;
        }
        ListNode* node=new ListNode();
        ListNode* head=node;//store the head of ans
        while(1)
        {
            pair<int,int>x=minheap.top();
            minheap.pop();
            node->val=x.first;
            if(lists[x.second]->next!=NULL)//check if end of list not reached
            {
                lists[x.second]=lists[x.second]->next;//traverse list further
                minheap.push({lists[x.second]->val,x.second});//push value of current pointer at this list
            }
            if(!minheap.empty())//still elements exist to insert in list
            {
                node->next=new ListNode();
                node=node->next;
            }
            else//all elements inserted and lists traversed
            {
                break;
            }
        }
        return head;
    }
};,38,https://leetcode.com/problems/merge-k-sorted-lists,https://leetcode.com/problems/merge-k-sorted-lists/solutions/3286041/two-solutions-using-minheap-and-ordered-set/,13,23,cpp

class Solution {
public:
    void nextPermutation(vector<int>& nums) {
        int n=nums.size(),i,j,y;
        for(i = n-2; i>=0; i--){
            if(nums[i]<nums[i+1]){
                break;
            }
        }
        if(i==-1){
            reverse(nums.begin(),nums.end());
            return;
        }y=-1;
        for(j = n-1; j >i; j--){
            if(nums[j]>nums[i]){
                y = j;
                break;
            }
        }
        swap(nums[i],nums[y]);
        reverse(nums.begin()+i+1,nums.end());
    }
};,48,https://leetcode.com/problems/next-permutation,https://leetcode.com/problems/next-permutation/solutions/3323626/simple-apprach-easy-to-understand/,14,31,cpp

class Solution {
public:
    int longestValidParentheses(string s) {
        int ans = 0, n = s.length();
        vector<int> v;
        for(int i = 0; i < n; i++){
            if(s[i]=='('){
                v.push_back(i);
            }else{
                if(!v.empty() && s[v.back()]=='(')v.pop_back();
                else v.push_back(i);
            }
        }
        if(v.empty()){
            return n;
        }
            // cout<<n<<" ";
        while(!v.empty()){
            ans = max(ans,n-v.back()-1);
            n = v.back();
            // cout<<n<<" ";
            v.pop_back();
        }
        return ans = max(ans,n);
    }
};,50,https://leetcode.com/problems/longest-valid-parentheses,https://leetcode.com/problems/longest-valid-parentheses/solutions/3587753/stack-c-very-easy/,15,32,cpp

class Solution {
public:
    int search(vector<int>& nums, int target) {
        int low = 0;
        int high = nums.size()-1;
        while(low<=high)
        {
            int mid = ( low + high ) / 2;
            if(nums[mid]== target) return mid;
            // left part
            if(nums[low] <= nums[mid])
            {
                if(nums[low] <= target && target <= nums[mid])
                {
                    high=mid-1;
                }
                else
                {
                    low = mid+1;
                }
            }
            else
            {
                if(nums[mid] <= target && target <= nums[high])
                {
                    low = mid+1;
                }
                else
                {
                    high = mid-1;
                }
            }
        }
        return -1;
    }
};,51,https://leetcode.com/problems/search-in-rotated-sorted-array,https://leetcode.com/problems/search-in-rotated-sorted-array/solutions/3849303/binary-search-solution/,16,33,cpp

public class Solution {
    public int[] SearchRange(int[] nums, int target) {
        if (nums == null || nums.Length == 0)
            return new int[] { -1, -1 };
        if (nums.Length==1){
            if(nums[0]==target) return new int[] {0,0};
        }
        // binary search until left is dif num or boundary
        int l=0,m=-1,r=nums.Length-1;
        int[] result = {-1,-1};
        while(l<=r){
            m=(l+r)/2;
            if(nums[m]<target)
                l=m+1;
            if(nums[m]>target)
                r=m-1;
            if(nums[m]==target){
                if(m==0){
                    result[0]=m;
                    break;
                }
                if(nums[m-1]!=target){
                    result[0]=m;
                    break;
                }
                r=m-1;
            }
        }
        m=-1;
        l=0;
        r=nums.Length-1;
        // do same with right
        while(l<=r){
            m=(l+r)/2;
            if(nums[m]<target)
                l=m+1;
            if(nums[m]>target)
                r=m-1;
            if(nums[m]==target){
                if(m==nums.Length-1){
                    result[1]=m;
                    break;
                }
                if(nums[m+1]!=target){
                    result[1]=m;
                    break;
                }
                l=m+1;
            }
        }
        return result;
    }
