class Solution {
public:
    bool isSafe(int curr_row, int curr_col, vector<vector<char>>& board, char value){
        //check if the value exists in the row
        int n = board.size();
        for(int col=0; col<n; col++){
            if(board[curr_row][col] == value){
                return false;
            }
        }

        //check if the value exists in the col
        for(int row=0; row<n; row++){
            if(board[row][curr_col] == value){
                return false;
            }
        }

        //check if the value exists in the respective 3*3 matrix
        for(int i=0; i<9; i++){
            if(board[3*(curr_row/3)+(i/3)][3*(curr_col/3)+(i%3)] == value){
                return false;
            }
        }

        return true;
    }


    bool solve(vector<vector<char>>& board){
        int n = board.size();
        for(int i=0; i<n; i++){
            for(int j=0; j<n; j++){
                //check for empty cell
                if(board[i][j] == '.'){
                    for(char value = '1'; value<='9'; value++){
                        //check if the value can be inserted
                        if(isSafe(i, j, board, value)){
                            board[i][j] = value;
                            //baaki recursion deklega
                            bool nextSolution = solve(board);
                            if(nextSolution == true){
                                return true;
                            }
                            else{
                                //backtrack
                                board[i][j] = '.';
                            }
                        }
                    }
                return false;
                }
            }
        }
        //all cells filled
        return true;
    }

    void solveSudoku(vector<vector<char>>& board) {
        solve(board);
    }
};,37,https://leetcode.com/problems/sudoku-solver,https://leetcode.com/problems/sudoku-solver/solutions/4361919/easy-understandable-c-solution-recursion-and-backtracking/,18,37,cpp

class Solution {
    public String countAndSay(int n) {
        String[] result = new String[n];
        result[0] = "1";
        for(int i=1; i<n; i++){
            result[i] = countAndSayOutput(result[i-1].toCharArray());
        }
        return result[n-1];
    }

    // Convert a string into it's countAndSay representation
    // We should send char array as input and StringBuilder to form as both are faster than directly dealing with Strings
    private String countAndSayOutput(char[] s){
        int count = 1;
        char c = s[0];
        StringBuilder sb = new StringBuilder(); 
        for(int i=1; i<s.length; i++){
            if(s[i]==c){
                count++;
            } else {

                sb.append(count);
                sb.append(c);
                c = s[i];
                count = 1; 
            }
        }
        sb.append(count);
        sb.append(c);
        return sb.toString(); 
    }
