/**
 * @param {number[]} candidates
 * @param {number} target
 * @return {number[][]}
 */
var combinationSum2 = function(candidates, target) {
    candidates = candidates.sort((a, b) => a - b);
    const output = [];
    const hashmap = new Map();

    const backtracking = (curr, remaining, target) => {
        if (target < remaining[0] || !remaining.length) return;
        const checkedHashmap = new Map();

        for (let i = 0; i < remaining.length; i++) {
            const number = remaining[i];
            if (checkedHashmap.has(number)) continue;
            if (number > target) return;

            const newRemaining = [...remaining];
            const newCurr = [...curr];
            newCurr.push(number);
            newRemaining.splice(i, 1);

            if (target - number === 0) {
                const key = newCurr.sort((a, b) => a - b).toString();
                if (hashmap.has(key)) return;
                hashmap.set(key, 1);
                return output.push(newCurr);
            }

            checkedHashmap.set(number, 1);
            backtracking(newCurr, newRemaining, target - number);
        }
    }

    backtracking([], candidates, target);

    return output;
};,47,https://leetcode.com/problems/combination-sum-ii,https://leetcode.com/problems/combination-sum-ii/solutions/3039439/js-easy-and-fast-solution-with-backtracking-and-hashmap/,20,40,javascript

class Solution {
public:
    void solve(int i,int &n,int k,vector<int> &v,vector<int> &tmp,vector<vector<int>> &ans){
        if(k==0){
            ans.push_back(tmp);
            return;
        }if(k<0)return;
        if(i>=n)return;
        for(int j = i; j < n; j++){
            tmp.push_back(v[j]);
            solve(j+1,n,k-v[j],v,tmp,ans);
            while(j+1<n&&v[j]==v[j+1]){
                j++;
            }
            tmp.pop_back();

        }

    }
    vector<vector<int>> combinationSum2(vector<int>& v, int k) {
        sort(v.begin(),v.end());
        vector<int> tmp;
        vector<vector<int>> ans;
        int n = v.size();
        solve(0,n,k,v,tmp,ans);
        return ans;
    }
};,50,https://leetcode.com/problems/combination-sum-ii,https://leetcode.com/problems/combination-sum-ii/solutions/3631115/optimized-c/,21,40,cpp

class Solution {
    public List<List<Integer>> combinationSum2(int[] candidates, int target) {
        List<List<Integer>> ans=new ArrayList<>();
        Arrays.sort(candidates);
        findCombinations(0,candidates,target,ans,new ArrayList());
        return ans;
    }
    private void findCombinations(int ind, int[] arr, int target, List<List<Integer>> ans, List<Integer> ds) {
        if(target == 0) {
            ans.add(new ArrayList<>(ds)); 
            return; 
        }

        for(int i = ind; i < arr.length;i++) {
            if(i > ind && arr[i] == arr[i-1]) continue; 
            if(arr[i]>target) break; 

            ds.add(arr[i]); 
            findCombinations(i+1, arr, target - arr[i], ans, ds); 
            ds.remove(ds.size() - 1); 
        }
    }
