class Solution {
public:
    void path(TreeNode* root, int& sum, int& num) {
        if (!root) 
            return;
        if (!root->left && !root->right) {
            sum += num * 10 + root->val;
            return;
        }
        num = num * 10 + root->val;
        path(root->left, sum, num);
        path(root->right, sum, num);
        num = num / 10;
    }

    int sumNumbers(TreeNode* root) {
        int sum = 0, num = 0;
        path(root, sum, num);
        return sum;
    }
