class Solution {
public:
    int canCompleteCircuit(vector<int>& A, vector<int>& B) {
        int gas = accumulate(A.begin(), A.end(), 0);
        int cost = accumulate(B.begin(), B.end(), 0);
        if (cost > gas) return -1;
        int tank = 0, initial = 0;
        for(int i = 0; i < A.size(); i++){
            if (!tank) initial = i;
            tank += A[i];
            tank -= B[i];
            if (tank < 0) tank = 0;
        }
        return initial;
    }
