    ListNode* insertionSortList(ListNode* head) {
        auto dummy = new ListNode(INT_MIN, head), cur = head;
        while(cur -> next) 
            if(cur -> next -> val > cur -> val) 
                cur = cur -> next;
            else {
                auto j = dummy, curNextNext = cur -> next -> next;
                while(j -> next -> val < cur -> next -> val)
                    j = j -> next;
                cur -> next -> next = j -> next;
                j -> next = cur -> next;
                cur -> next = curNextNext;
            }

        return dummy -> next;
    }
