    int maxProfit(int k, vector<int>& prices) {
        int n = prices.size();
        vector<vector<vector<int>>> dp(n+1,vector<vector<int>>(2,vector<int>(k+1,0)));

        for(int i=n-1;i>=0;i--){
            for(int j=1;j>=0;j--){
                for(int l=k;l>=1;l--){
                    if(j == 0) 
                        dp[i][j][l] = max(-prices[i]+dp[i+1][1][l],dp[i+1][0][l]);
                    else
                        dp[i][j][l] = max(prices[i]+dp[i+1][0][l-1],dp[i+1][1][l]);
                }
            }
        }
        return dp[0][0][k];
    }
