class Solution {
public:

    void swap(TreeNode* curr){
        if(!curr){
            return;
        }
        swap(curr->left);
        swap(curr->right);
        TreeNode* t;
        t=curr->left;
        curr->left=curr->right;
        curr->right=t;
    }
    TreeNode* invertTree(TreeNode* root) {
        swap(root);
        return root;

    }
