class Array
    def sorted(k)
        self[0...k].sort
    end

    def locate(v)
        bsearch_index {|w| w >= v}
    end

    def add_sorted!(v)
        insert(locate(v) || -1, v)
    end

    def del_sorted!(v)
        delete_at(locate(v))
    end

    def slide!(d, a)
        del_sorted!(d)
        add_sorted!(a)
        last
    end
end

