class Solution {
private:

    int solveMemoization(int n, vector<int> &dp)
    {
        if(n==0)
            return 1;
        if(n<0)
            return 0;

        if(dp[n]!=-1)
            return dp[n];

        int start=1;
        int end=sqrt(n);
        int result = INT_MAX;
        for(int i=start;i<=end;i++)
        {
            int numSquare=i*i;
            int ans = 1+solveMemoization(n-numSquare, dp);
            result = min(ans, result);
        }

        dp[n]=result;
        return dp[n];
    }

public:
    int numSquares(int n) {
        vector<int> dp(n+1, -1);
        int ans = solveMemoization(n, dp);
        return ans-1;
    }
