class Solution {
public:
    int combinationSum4(vector<int>& nums, int target) {
        vector<unsigned int> dp(target + 1, 0);  // value should not be negative
        dp[0] = 1; // Base case: There is one way to make a sum of 0 (by not choosing any element).
        for (int i = 1; i <= target; ++i) {
            for (int num : nums) {
                if (i >= num) {
                    dp[i] += dp[i - num];
                }
            }
        }  
        return dp[target];
    }
