class Solution {
    public int findMaximizedCapital(int k, int w, int[] profits, int[] capital) {
        int n=profits.length;
        PriorityQueue<Integer[]> pq =new PriorityQueue<Integer[]> ((a,b)->(a[1]-b[1]));
        for(int i=0;i<n;i++)
            pq.add(new Integer[] {profits[i],capital[i]});
        PriorityQueue<Integer[]> max =new PriorityQueue<Integer[]> ((a,b)->(b[0]-a[0]));

        while((pq.size()!=0||max.size()!=0)&&k>0)
        {
            if(!pq.isEmpty()&&pq.peek()[1]<=w)
            {
                max.add(pq.poll());
            }
            else
            {
                if(!max.isEmpty())
                {
                    w+=max.poll()[0];
                    k--;
                }
                else
                    break;
            }
        }

        return w;

    }
