let findRotateSteps = (ring, key, m = new Map()) => {
    let M = ring.length,
        N = key.length;
    let steps = (i, k) => {
        let x = Math.abs(i - k);
        return Math.min(x, M - x); // ⭐️ minimum x steps to rotate the ring from i..k (🚫 without wrap-around, ✅ with wrap-around)
    };
    let go = (i = 0, j = 0, best = Infinity) => {
        let hash = `${i},${j}`;
        if (m.has(hash))
            return m.get(hash); // 🤔 memo
        if (j == N)
            return m.set(hash, 0).get(hash); // 🛑 base case
        for (let k = 0; k < M; ++k)
            if (ring[k] == key[j])
                best = Math.min(best, 1 + steps(i, k) + go(k, j + 1)); // 🎯 min steps to reach key[j] from each ring[i] is the min steps to reach key[j + 1] from ring[k], 🔍 find optimal k via exhaustive search
        return m.set(hash, best).get(hash);
    };
    return go(); // 🚀 when the ring starts at i = 0 (ie. index 0 is aligned with the 12:00 direction of the ring) return the min steps to construct key[j = 0..N - 1]
};,177,https://leetcode.com/problems/freedom-trail,https://leetcode.com/problems/freedom-trail/solutions/1147789/the-art-of-dynamic-programming/,173,514,javascript

