class Solution {
public:
    int findUnsortedSubarray(vector<int>& nums) {
        vector<int> sorted_nums = nums;
        sort(sorted_nums.begin(), sorted_nums.end());

        int start = 0, end = nums.size() - 1;

        // Find the first index where elements are different from the sorted array
        while (start < nums.size() && nums[start] == sorted_nums[start]) {
            start++;
        }

        // Find the last index where elements are different from the sorted array
        while (end >= 0 && nums[end] == sorted_nums[end]) {
            end--;
        }

        // If the array is already sorted, return 0
        // Otherwise, return the length of the subarray that needs to be sorted
        return (end <= start) ? 0 : end - start + 1;
    }
};,25,https://leetcode.com/problems/shortest-unsorted-continuous-subarray,https://leetcode.com/problems/shortest-unsorted-continuous-subarray/solutions/3600522/c-simplest-code-with-comments-sorting/,192,581,cpp

class Solution {
public:
    int findUnsortedSubarray(vector<int>& nums) {
      int n = nums.size();
      vector<int> l(n), r(n);
      int mn = 1e9, mx = -1e9;

      for(int i=0; i<n; i++) {
          mx = max(mx, nums[i]);
          l[i] = mx;

          mn = min(mn, nums[n - i - 1]);
          r[n - i - 1] = mn;
      }

      int s = -1, e = -1;
      for(int i=0; i<n; i++) {
          if(l[i] > r[i] && s == -1) s = i;
          if(l[n - i - 1] > r[n - i - 1] && e == -1) e = n - i - 1;
      }
      return s == -1 ? 0 : e - s + 1;
    }
};

