class Solution {
public:
    vector<int> postorder(Node* root) {
       if (!root) return {};
       vector<int> ans;
       stack<Node*> st;
       unordered_map <Node*, bool> areChildrenSeen;
       st.push(root);
       while (!st.empty()) {
            Node* node = st.top();
            if (!node->children.empty() && !areChildrenSeen[node]) {
                areChildrenSeen[node] = true;
                for (int i=node->children.size()-1; i>=0; i--) {
                    st.push(node->children[i]);
                }
            }
            else {
                ans.push_back(node->val);
                st.pop();
            }
       } 
       return ans;
    }
};,112,https://leetcode.com/problems/n-ary-tree-postorder-traversal,https://leetcode.com/problems/n-ary-tree-postorder-traversal/solutions/4014838/c-3-possible-solutions-in-simple-and-clean-code-including-without-reverse/,195,776,cpp

