class Solution {
public:
    int triangleNumber(vector<int>& arr) {

        int n = arr.size(),ans = 0;
        sort(arr.begin(),arr.end());

        if(n<=2) return 0;
        if(n==3) return (arr[0]+arr[1]>arr[2]);
        int i = 0;

        while(!arr[i]) i++;

        for(;i<n-2;i++)
        {
            for(int j = i+1;j<n-1;j++)
            {
               int sum = arr[i]+arr[j];
               int num = lower_bound(arr.begin(),arr.end(),sum)-arr.begin();
               ans+=(num-j-1);
            }
        }
        return ans; 
    }
