class Solution {
    public int widthOfBinaryTree(TreeNode root) {
      if(root==null)
          return 0;
        Queue<Pair<TreeNode,Integer>> q=new LinkedList();
            q.offer(new Pair(root,0 ));
        int ans=1;
        while(!q.isEmpty())
        {
            int n=q.size();
            int sta=q.peek().getValue();
            int ind=0;
            for(int i=0;i<n;i++)
            {
                Pair<TreeNode,Integer> temp=q.poll();
                TreeNode help=temp.getKey();
                ind=temp.getValue();
                if(help.left!=null)
                    q.add(new Pair(help.left,2*ind+1));
                 if(help.right!=null)
                    q.add(new Pair(help.right,2*ind+2));
            }
            ans=Math.max(ans,ind-sta+1);
        }
        return ans;
    }
