class MapSum {
    private final TrieNode root;

    public MapSum() {
        this.root = new TrieNode(0);
    }

    public void insert(String key, int val) {
        TrieNode node = this.root;

        for(int i = 0; i < key.length(); ++i) {
            final int index = key.charAt(i) - 'a';

            if(node.children(index) == null)
                node.children(index, new TrieNode(0));

            node = node.children(index);
        }

        node.value(val);
    }

    public int sum(final String prefix) {
        return sumHelper(prefix, 0, this.root);
    }

    private int sumHelper(String prefix, int i, TrieNode root) {
        if(root == null)
            return 0;

        if(i == prefix.length()) {
            int sum = 0;

            for(int j = 0; j < 26; ++j) {
                TrieNode node = root.children(j);

                if(node != null)
                    sum += sumHelper(prefix, i, node) + node.value();
            }

            return sum;
        }

        final int index = prefix.charAt(i) - 'a';

        if(root.children(index) != null && i == prefix.length() - 1)
            return sumHelper(prefix, i + 1, root.children(index)) + root.children(index).value();

        return sumHelper(prefix, i + 1, root.children(index));
    }

    private final class TrieNode {
        private final TrieNode[] children;
        private int value;

        public TrieNode(final int value) {
            this.value = value;
            this.children = new TrieNode[26];
        }

        public void value(final int value) {
            this.value = value;
        }

        public int value() {
            return this.value;
        }

        public void children(final int index, final TrieNode node) {
            this.children[index] = node;
        }

        public TrieNode children(final int index) {            
            return this.children[index];
        }
    }
}

