    int findShortestSubArray(vector<int>& nums) {

        int n = nums.size(), maxf = 0;
        unordered_map<int, pair<int, pair<int, int>>> mp;

        for (int i=0; i<n; i++) {
            if (!mp.count(nums[i])) mp[nums[i]].second.first = i;
            mp[nums[i]].second.second = i;
            maxf = max(maxf, ++mp[nums[i]].first);
        }

        int ans = n;
        for (auto i: nums)
            if (mp[i].first == maxf)
                ans = min(ans, mp[i].second.second - mp[i].second.first + 1);

        return ans;
    }
