class Solution {
public:
    const int mod = 26;
    string shiftingLetters(string s, vector<int>& arr) {

        //we are given the information that 
        //(s.length() == shifts.length())

        //prefix vector to roll the characters 
        vector<long long int>prefix(s.length()+1,0);

        //we need to put  1 on index zero 
        //we need to put -1 on index (i+1)
        for(int i=0;i<arr.size();i++)
        {
            long long int val = arr[i];   
            prefix[0] += val;
            prefix[i+1] -= val;
        }
        for(int i=0;i<arr.size();i++)
        {
            if(i == 0) continue;
            prefix[i] = prefix[i] + prefix[i-1];
        } 
        for(int i=0;i<arr.size();i++)
        {
            char prv_ch = s[i];

            long long int val = prv_ch - 'a';

            val = (val + prefix[i])%mod;

            char new_ch = 'a' + val;

            s[i] = new_ch;         
        }
        return s;
    }
