class Solution {
    static final int MAX_N = 20;
    static TreeNode[][] trees = new TreeNode[MAX_N + 1][];

    public List<TreeNode> allPossibleFBT(int n) {
        if (trees[1] == null) {
            // The static array trees[][] will contain all full 
            // binary trees from n=1 to n=19 (skip even numbers).
            //
            // Build the static array trees[][] during the first  
            // test case.  The values in the array trees[][] 
            // will persist through all of the test cases of the 
            // submit.  More standard static initialization ran 
            // slower, so this non-standard static variable 
            // initialization was used for extra speed.
            //
            // Build larger trees by creating a root node, then 
            // linking the root's left and right children to 
            // trees with smaller n values.  Very cross-linked 
            // trees.
            //
            // n == even number ==> Zero Configurations
            // Never any "full binary trees" with an even number 
            // of nodes, because full binary trees have all nodes 
            // in pairs except the single root node, which will 
            // always require an odd number of nodes.
            trees[0] = new TreeNode[0];
            for (int i = 2; i <= MAX_N; i += 2)  trees[i] = trees[0];

            // n == 1 : Configurations=1 - A single node with no 
            // children.
            trees[1] = new TreeNode[1];
            trees[1][0] = new TreeNode();

            // n == 3 : Configurations=1 - Root with a single node 
            // for both left and right child.
            trees[3] = new TreeNode[1];
            trees[3][0] = new TreeNode();
            trees[3][0].left = trees[3][0].right = trees[1][0];

            // n == 5..19 (odd n only) : 
            // Configurations=sum(configs(1..n-2) x configs(n-2..1))
            // Use lower numbered configurations to build all the 
            // configurations for n >= 5.
            for (int m = 5; m <= MAX_N; m += 2) {
                // Calculate how many configurations of trees for 
                // n==m nodes.
                int configCount = 0;
                for (int i = 1; i < m; i++)
                    configCount += trees[i].length * trees[m - i - 1].length;
                // Build all possible configs for n==m
                TreeNode[] configs = trees[m] = new TreeNode[configCount];
                int configsIdx = 0;
                for (int i = 1; i < m; i++) {
                    for (TreeNode left : trees[i]) {
                        for (TreeNode right : trees[m - i - 1]) {
                            configs[configsIdx] = new TreeNode();
                            configs[configsIdx].left = left;
                            configs[configsIdx++].right = right;
                        }
                    }
                }
            }
        }

        // Arrays of trees have been built for all possible values of 
        // n == 1..MAX_N.  So all that is needed is to return the array 
        // of trees as a list of trees.
        return Arrays.asList(trees[n]);
    }
