class Solution {
public:
    int minFlipsMonoIncr(string str) {
        int n = str.length(),i;
        vector<int> p(n,0),s(n,0);
        p[0] = (str[0]=='1');
        for(i = 1; i < n; i++){
            if(str[i]=='1'){
                p[i] = p[i-1]+1;
            }else{
                p[i] = p[i-1];
            }
        }
        s[n-1] = (str[n-1]=='0');
        for(i = n-2; i >= 0; i--){
            if(str[i]=='0'){
                s[i] = s[i+1]+1;
            }else{
                s[i] = s[i+1];
            }
        }
        int ans = n;
        ans  = min(s[0],p[n-1]);
        for(i=1;i<n;i++){
            ans = min(ans,p[i-1]+s[i]);
        }
        return ans;
    }
