            while(j<emails[i].size())
            {
                if(emails[i][j]=='.' && flag1==0)
                {
                    emails[i].erase(emails[i].begin()+j);
                }
                else if(emails[i][j]=='@')
                {
                    flag1=1;
                    j++;
                }
                else if(emails[i][j]=='+' && flag1==0)
                {
                    while(emails[i][j]!='@')
                    {
                        emails[i].erase(emails[i].begin()+j);
                    }
                }
                else
                {
                    j++;
                }
            }
        }
        i=0;
        while(i<emails.size())
        {
            j=i+1;
            while(j<emails.size())
            {
                if(emails[i]==emails[j])
                {
                    emails.erase(emails.begin()+j);
                }
                else
                {
                    j++;
                }
            }
            i++;
        }
        count = emails.size();
        return count;
    }
