            if(ch=='a')
                st.push(ch);
            else if(ch=='b'){
                if(!st.empty()&&st.top()=='a')
                    st.push(ch);
                else
                    return false;
            }
            else
            {
                if(!st.empty()&&st.top()=='b'){
                    st.pop();
                        if(!st.empty()&&st.top()=='a')
                            st.pop();
                        else return false;
                    }
                else
                    return false;
            }
        }
        return st.empty();
    }
