class Solution {
    char [] parent = new char[26]; // make a parent array of size 26

     // find function used for finding parent of charter ch
    public char find(char ch)
    {
        // standard base condition of find function, 
        // at any point parent of this character equals to itself only return
        if(parent[ch - 'a'] == ch)
            return ch;

        // else move on in finding parent
        return parent[ch - 'a'] = find(parent[ch - 'a']);
    }

    // Union function to merge parents of them
    public void Union(char first, char second)
    {
        // extract parent of both characters
        char ParentOfFirst = find(first);
        char ParentOfSecond = find(second);

        // whichever parent is less than other, 
        // make that parent
        if(ParentOfFirst < ParentOfSecond)
        {
            parent[ParentOfSecond - 'a'] = ParentOfFirst;
        }
        else
        {
            parent[ParentOfFirst - 'a'] = ParentOfSecond;
        }
    }

    public String smallestEquivalentString(String s1, String s2, String baseStr) {
        int n = s1.length(); // extract size

        // Intially, all are the parents of themselves only
        for(char c = 'a'; c <= 'z'; c++)
        {
            parent[c - 'a'] = c;
        }

        // now, apply Union function on s1 and s2
        for(int i = 0; i < n; i++)
        {
            Union(s1.charAt(i), s2.charAt(i));
        }

        // finally return ans;
        String ans = "";
        for(int i = 0; i < baseStr.length(); i++)
        {
            ans += find(baseStr.charAt(i));
        }

        return ans;
    }
