            n = q.size();
            s = 0;
            while(n--){
                node = q.front();q.pop();
                s += node->val;
                if(node->left)q.push(node->left);
                if(node->right)q.push(node->right);
            }
            if(s>y){
                y = s;
                z = x;
            }
            x++;
        }
        return z;
