vector<vector<long long>> operator*(vector<vector<long long>>& A, vector<vector<long long>>& B)
{// TC: O(A.row*A.cols*B.cols)
    if (A[0].size()!=B.size()) return {{}};
    vector<vector<long long>> C(A.size(), vector<long long>(B[0].size(), 0));
    #pragma unroll
    for (int i=0; i<A.size(); i++)
        for(int j=0; j<B[0].size(); j++){
            for(int k=0; k<A[0].size(); k++)
                C[i][j]=(C[i][j]+A[i][k]*B[k][j])%mod;
        }
    return C;
}
vector<vector<long long>> matrixExp(vector<vector<long long>> A, int n) 
{// TC: O(log n) Use binary expression for n
    if (n == 0) return Id;
    vector<vector<long long>> result = Id;
    while (n > 0) {
        if (n&1) 
            result = result * A;//Matrix multiplication
        A = A*A;//Matrix square
        n>>=1;
    }
    return result;
}

