class Solution {
public:
    int mod = 1e9 + 7 ;
    int solve(int n ,unordered_map<int,vector<int>> &mapp,int temp,vector<vector<int>> &dp)
    {
        if(n == 1)
            return 1 ;

        if(dp[n][temp] != -1)
            return dp[n][temp] ;

        int ans = 0 ;
        for(auto x: mapp[temp])
            ans = (ans % mod  +  solve(n-1, mapp, x, dp)% mod ) % mod ;

        return dp[n][temp] = ans ;
    }
    int countVowelPermutation(int n) 
    {
        unordered_map<int,vector<int>> mapp ;
        vector<vector<int>> dp(n+1,vector<int> (6,-1)) ;
        int ans = 0  ;

        mapp[1].push_back(2) ;

        mapp[2].push_back(1) ;
        mapp[2].push_back(3) ;

        mapp[3].push_back(1) ;
        mapp[3].push_back(2) ;
        mapp[3].push_back(4) ;
        mapp[3].push_back(5) ;

        mapp[4].push_back(3) ;
        mapp[4].push_back(5) ;

        mapp[5].push_back(1) ;

        ans = (ans % mod  +  solve(n, mapp, 1, dp)) % mod ;
        ans = (ans % mod +  solve(n, mapp, 2, dp)) % mod  ;
        ans = (ans % mod +  solve(n, mapp, 3, dp)) % mod  ;
        ans = (ans % mod  +  solve(n, mapp, 4, dp)) % mod ;
        ans = (ans % mod +  solve(n, mapp, 5, dp)) % mod  ;

        return ans ;
    }
