class DisjointSet {
    public : 
        vector<int> parent,size;
        DisjointSet(int n) {
            parent.resize(n+1);
            size.resize(n+1);

            for(int i=0;i<=n;i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        int findUPar(int node) {
            if(parent[node] == node)
                return node;

            return parent[node] = findUPar(parent[node]);
        }


        void unionBySize(int u,int v) {
            int ultU = findUPar(u);
            int ultV = findUPar(v);

            if(ultU == ultV)
                return;

            if(size[ultU] < size[ultV]) {
                parent[ultU] = ultV;
                size[ultV] += size[ultU];
                size[ultU] = 0;
            }
            else {
            parent[ultV] = ultU;
            size[ultU] += size[ultV];  // Fix: Update size of the new root node
            size[ultV] = 0;
        }
        }
};

