#define mod 1000000007
class Solution {
public:
    int res, sum;
    int preorder(TreeNode* root) {
        if(root != NULL) {
            int left = preorder(root->left);
            int right = preorder(root->right);
            return root->val += left + right;
        }
        return 0;
    }
    void solve(TreeNode* root) {
        if(root != NULL) {
            solve(root->left);
            solve(root->right);
            if(abs(sum - 2 * root->val) < abs(sum - 2 * res)) res = root->val;
        }
    }
    int maxProduct(TreeNode* root) {
        res = 0;
        sum = preorder(root);      
        solve(root);
        long long ans = (long long)(((sum - res) % mod) * (long long)(res % mod));
        return ans % mod;
    }
