class Solution {
public:
    int longestZigZag(TreeNode* r) {
        int res = 0;
        bool l =true;
        solve(r,res,l,0);
        solve(r,res,!l,0);
        return res;

    }

    void solve(TreeNode* r,int &res, bool l, int t)
    {
        if(!r)
            return;
        res = max(res, t);
        if(l)
        {
            solve(r->left,res,!l,t+1);
            solve(r->right,res,l,1);
        }
        else
        {
            solve(r->right,res,!l,t+1);
            solve(r->left,res,l,1);
        }
    }
