#define vv pair<int ,vector<int>>
class Solution {
public:
    int kthSmallest(vector<vector<int>>& mat, int k)
    {
        int m=mat.size(),n=mat[0].size();
        priority_queue<vv,vector<vv>,greater<vv>> q;
        vector<int> temp(m,0);
        int s=0;
        for(int i=0;i<m;i++)
        {
            s+=mat[i][0];
        }
        q.push({s,temp});
        map<vector<int>,int> vis;
        vis[temp]=1;
        int x=0;
        while(!q.empty())
        {
            auto p=q.top();
            q.pop();
            s=p.first;
            temp=p.second;
            x++;
            if(x==k)
            {
                return s;
            }
            for(int i=0;i<m;i++)
            {
                s=p.first;
                temp=p.second;
                int j=temp[i];
                s-=mat[i][j];
                if(j+1<n)
                {
                    s+=mat[i][j+1];
                    temp[i]=j+1;
                }
                if(j+1<n&&vis.find(temp)==vis.end())
                {
                    vis[temp]=1;
                    q.push({s,temp});
                }

            }
        }
        return 0;


    }
};
