        // The idea in here is pretty simple. We will find the maximum two elemens of the nums vector and then return the required answer.
        int firstMax  = -1;
        int secondMax = -1;
        for(auto &ele : nums){
            if(ele > firstMax) {
                secondMax = firstMax;
                firstMax  = ele;
            }
            else if(ele > secondMax) secondMax = ele;
        }
        return (firstMax - 1) * (secondMax - 1);
    }
