class Solution {
    public int longestSubarray(int[] nums) {
        int n = nums.length;
        int i = 0, j = 0, count_before_0 = 0, count_after_0 = 0, maxi = 0;
        boolean is_0_present = false;

        while (j < n) {
            if (nums[j] == 0) {
                if (!is_0_present) {
                    is_0_present = true;
                } else {
                    maxi = Math.max(maxi, count_before_0 + count_after_0);
                    count_before_0 = count_after_0;
                    count_after_0 = 0;
                }
            } else {
                if (!is_0_present) {
                    count_before_0++;
                }
                if (is_0_present) {
                    count_after_0++;
                }
            }
            j++;
        }
        maxi = Math.max(maxi, count_before_0 + count_after_0);
        return is_0_present ? maxi : maxi - 1;
    }
