class Solution {
public:
    bool isPathCrossing(string path) {
        // Map to store the moves corresponding to each direction
        unordered_map<char, pair<int, int>> moves;
        moves['N'] = {0, 1}; // North: increment in y-coordinate
        moves['S'] = {0, -1}; // South: decrement in y-coordinate
        moves['W'] = {-1, 0}; // West: decrement in x-coordinate
        moves['E'] = {1, 0}; // East: increment in x-coordinate

        // Set to store visited coordinates
        unordered_set<string> visited;
        visited.insert("0,0"); // Starting point (0,0)

        int x = 0; // Current x-coordinate
        int y = 0; // Current y-coordinate

        // Traverse the path and check for crossing
        for (char c : path) {
            // Get the current move
            pair<int, int> curr = moves[c];
            int dx = curr.first; // Change in x-coordinate
            int dy = curr.second; // Change in y-coordinate

            // Update the coordinates
            x += dx;
            y += dy;

            // Create a hash representing the current coordinates
            string hash = to_string(x) + "," + to_string(y);

            // Check if the current coordinates have been visited before
            if (visited.find(hash) != visited.end()) {
                return true; // Path has crossed itself
            }

            // Mark the current coordinates as visited
            visited.insert(hash);
        }

        return false; // No crossing detected
    }
};




