class Solution {
public:
    const int mod = 1e9+7;
    int numOfSubarrays(vector<int>& arr) 
    {
        //we will use 2d dp for generating the ans
        //dp of size 2 * arr.size()

        //making dp for storing the even count and odd count till index i
        vector<vector<long long int>>dp;

        //initializing the dp with 0
        dp.resize(2,vector<long long int>(arr.size()+1,0));


        for(int j=1;j<dp[0].size();j++)
        {
            long long int ele = arr[j-1];

            if((ele % 2) == 0)
            {
                long long int prv_oc = dp[0][j-1]%mod;
                long long int prv_ec = dp[1][j-1]%mod;

                //creating odd count
                dp[0][j] = (prv_oc%mod);

                //creating even count
                dp[1][j] = ((prv_ec%mod) + (1%mod))%mod;
            } 
            else if((ele % 2) != 0)
            {
                long long int prv_oc = dp[0][j-1]%mod;
                long long int prv_ec = dp[1][j-1]%mod;

                //creating odd count
                dp[0][j] = ((prv_ec%mod) + (1%mod))%mod;

                //creaing the even count
                dp[1][j] = (prv_oc%mod);
            }
        }
        long long int count = 0;
        for(int j=0;j<dp[0].size();j++)
        {
            //cout<<dp[0][j]<<" ";
            count = ((count % mod) + (dp[0][j]%mod))%mod;
        }
        return count%mod;
    }
};,145,https://leetcode.com/problems/number-of-sub-arrays-with-odd-sum,https://leetcode.com/problems/number-of-sub-arrays-with-odd-sum/solutions/3268520/dp-very-easy-to-understand-must-see/,394,1631,cpp

