class Solution {
public:
    int findLengthOfShortestSubarray(vector<int>& A) {
        int N = A.size(), left = 0, right = N - 1;
        while (left + 1 < N && A[left] <= A[left + 1]) ++left;
        if (left == A.size() - 1) return 0;
        while (right > left && A[right - 1] <= A[right]) --right;
        int ans = min(N - left - 1, right), i = 0, j = right;
        while (i <= left && j < N) {
            if (A[j] >= A[i]) {
                ans = min(ans, j - i - 1);
                ++i;
            } else ++j;
        }
        return ans;
    }
};,172,https://leetcode.com/problems/shortest-subarray-to-be-removed-to-make-array-sorted,https://leetcode.com/problems/shortest-subarray-to-be-removed-to-make-array-sorted/solutions/830480/c-o-n-sliding-window-explanation-with-illustrations/,406,1679,cpp

class Solution {
public:
    int countTriplet(vector<int> &nums1,vector<int> &nums2)
    {
        int ans=0,left,right;
        unordered_map<int,int> freq;
        for(auto &n:nums2)
        {
            freq[n]++;
        }
        for(int i=0;i<nums1.size();i++)
        {
            long long t=(long long)nums1[i]*nums1[i];
            left=0;
            right=nums2.size()-1;
            while(left<right)
            {
                long long temp=(long long)nums2[left]*nums2[right];
                if(t==temp)
                {
                    if(nums2[left]==nums2[right])
                    {
                        ans+=(freq[nums2[left]]*(freq[nums2[left]]-1))/2;
                            break;
                    }
                    ans+=freq[nums2[left]]*freq[nums2[right]];
                    left+=freq[nums2[left]];
                    right-=freq[nums2[right]];
                }
                else if(t>temp)
                {
                    left+=freq[nums2[left]];
                }
                else
                {
                    right-=freq[nums2[right]];
                }
            }
        }
        return ans;
    }
    int numTriplets(vector<int>& nums1, vector<int>& nums2)
    {
        sort(nums1.begin(),nums1.end());
        sort(nums2.begin(),nums2.end());
        return countTriplet(nums1,nums2)+countTriplet(nums2,nums1);

    }
};
