        vector<int> pairing(n); 
        for(vector<int> pair : pairs){ // Pair the friend with their given paired person
            pairing[pair[0]]=pair[1];
            pairing[pair[1]]=pair[0];
        }
        int ans=0;
        for(int i=0; i<n; i++){
            for(int j=0; j<n-1; j++){
                if(pref[i][j]==pairing[i])   break; // If the friend is paired with their prefered person then break since they are not unhappy
                if(isUnhappy(n, pref, pairing, i, pref[i][j])){ // If friend is not paired with their most prefered person, check if they are unhappy
                    ans++; // If unhappy then increment ans
                    break;
                }
            }
        }
        return ans;
    }
