                int ind = s[j] - 'a';
                cnt[ind]++;
                max_f = max(max_f, cnt[ind]);
                min_f = cnt[ind];
                for(int k=0; k<26; k++) {
                    if(cnt[k] >= 1)
                        min_f = min(min_f, cnt[k]);
                }
                ans += (max_f - min_f);
            }
        }
        return ans;
    }
