public class Solution {
    public int FindCenter(int[][] edges) {
        Dictionary<int,int> d=new();
        for(int i=0;i<edges.Length;i++){
            if(d.ContainsKey(edges[i][0]))
                d[edges[i][0]]++;
            else
                d[edges[i][0]]=0;
            if(d.ContainsKey(edges[i][1]))
                d[edges[i][1]]++;
            else
                d[edges[i][1]]=0;
        }
        // now we just gotta find key with max val
        int max=0,result=0;
        foreach(KeyValuePair<int,int> kvp in d){
            if(kvp.Value>max){
                max=kvp.Value;
                result=kvp.Key;
            }
        }
        return result;
    }
