function getNumberOfBacklogOrders(orders) {
  const MOD = 1e9 + 7
  const BUY = 0
  const SELL = 1
  const minSellers = new PriorityQueue({ compare: (a, b) => a[0] - b[0] })
  const maxBuyers = new PriorityQueue({ compare: (a, b) => b[0] - a[0] })
  for (const [currentOrderPrice, currentOrders, orderType] of orders) {
    switch (orderType) {
      case BUY:
        {
          let [buyMaxPriceForEachUnit, buyCount] = [currentOrderPrice, currentOrders]
          while (buyCount > 0 && !minSellers.isEmpty()
                 && minSellers.front()[0] <= buyMaxPriceForEachUnit) {
            const [sellerPrice, sellerOrderCount] = minSellers.dequeue()
            const buyCountPossible = Math.min(buyCount, sellerOrderCount)
            buyCount -= buyCountPossible
            const sellerOrderCountRemaining = sellerOrderCount - buyCountPossible
            if (sellerOrderCountRemaining > 0) {
              minSellers.enqueue([sellerPrice, sellerOrderCountRemaining])
            }
          }
          if (buyCount > 0) maxBuyers.enqueue([buyMaxPriceForEachUnit, buyCount])
        }
        break
      case SELL:
        {
          let [sellMinPriceForEachUnit, sellCount] = [currentOrderPrice, currentOrders]
          while (sellCount > 0 && !maxBuyers.isEmpty()
                 && maxBuyers.front()[0] >= sellMinPriceForEachUnit) {
            const [buyerPrice, buyerOrderCount] = maxBuyers.dequeue()
            const sellCountPossible = Math.min(sellCount, buyerOrderCount)
            sellCount -= sellCountPossible
            const buyerOrderCountRemaining = buyerOrderCount - sellCountPossible
            if (buyerOrderCountRemaining > 0) {
              maxBuyers.enqueue([buyerPrice, buyerOrderCountRemaining])
            }
          }
          if (sellCount > 0) {
            minSellers.enqueue([sellMinPriceForEachUnit, sellCount])
          }
        }
        break
    }
  }
  let backlog = 0
  while (!maxBuyers.isEmpty()) {
    const [buyerPrice, buyerOrderCount] = maxBuyers.dequeue()
    backlog += buyerOrderCount
    backlog %= MOD
  }
  while (!minSellers.isEmpty()) {
    const [sellerPrice, sellerOrderCount] = minSellers.dequeue()
    backlog += sellerOrderCount
    backlog %= MOD
  }
  return backlog
}
